/* ---------------------------------------------------------------- database */
function db_file(): string {
    static $f = null;
    if ($f === null) { $cfg = is_file(DATA . '/config.php') ? (include DATA . '/config.php') : []; $f = DATA . '/' . ($cfg['db'] ?? 'kiratora.sqlite'); }
    return $f;
}
function db(): PDO {
    static $pdo = null;
    if ($pdo) return $pdo;
    $fresh = !is_file(db_file());
    $pdo = new PDO('sqlite:' . db_file(), null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
    $pdo->exec('PRAGMA foreign_keys = ON; PRAGMA busy_timeout = 5000;');
    if ($fresh) $pdo->exec(schema_sql());
    migrate($pdo);
    return $pdo;
}
// Brings an existing database up to date (new tables and columns). Safe to run on every request: it stops after one quick check.
const SCHEMA_VERSION = 2;
function migrate(PDO $pdo): void {
    $v = (int)($pdo->query("SELECT value FROM settings WHERE key = 'schema_version'")->fetchColumn() ?: 1);
    if ($v >= SCHEMA_VERSION) return;
    $cols = fn($t) => array_column($pdo->query("PRAGMA table_info($t)")->fetchAll(), 'name');
    if ($v < 2) {
        $pdo->exec("CREATE TABLE IF NOT EXISTS reviews (
          id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, location TEXT NOT NULL DEFAULT '', rating INTEGER NOT NULL DEFAULT 5,
          title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL, product_id INTEGER, photo TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT '',
          review_date TEXT NOT NULL DEFAULT (date('now')), published INTEGER NOT NULL DEFAULT 1, featured INTEGER NOT NULL DEFAULT 0,
          created_at TEXT NOT NULL DEFAULT (datetime('now')))");
        $pdo->exec('CREATE INDEX IF NOT EXISTS ix_reviews_product ON reviews(product_id)');
        if (!in_array('weight_kg', $cols('products'), true)) $pdo->exec('ALTER TABLE products ADD COLUMN weight_kg REAL');
        $oc = $cols('orders');
        if (!in_array('btc_amount', $oc, true)) $pdo->exec('ALTER TABLE orders ADD COLUMN btc_amount TEXT');
        if (!in_array('btc_rate', $oc, true)) $pdo->exec('ALTER TABLE orders ADD COLUMN btc_rate REAL');
        if (!in_array('weight_kg', $oc, true)) $pdo->exec('ALTER TABLE orders ADD COLUMN weight_kg REAL');
    }
    $pdo->prepare("INSERT INTO settings(key, value) VALUES('schema_version', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value")->execute([(string)SCHEMA_VERSION]);
}
function q(string $sql, array $args = []): PDOStatement {
    $st = db()->prepare($sql);
    $st->execute($args);
    return $st;
}
function one(string $sql, array $args = []) { $r = q($sql, $args)->fetch(); return $r === false ? null : $r; }
function all(string $sql, array $args = []): array { return q($sql, $args)->fetchAll(); }
function val(string $sql, array $args = []) { $r = q($sql, $args)->fetchColumn(); return $r === false ? null : $r; }

