@media(max-width:860px){.side{position:static;width:auto;flex-direction:row;flex-wrap:wrap;align-items:center;padding:10px}.side nav{flex-direction:row;flex-wrap:wrap}.side-foot{flex-direction:row;border:0}.main{margin:0;padding:20px 14px 60px}}
